def parse_bool(value: str) -> bool:
    normalized = value.strip().lower()
    if normalized in ("yes", "true", "1", "y"):
        return True
    if normalized in ("no", "false", "0", "n"):
        return False
    raise ValueError(f"Unknown boolean value: {value!r}")

